import unittest
from candidate import remove_vowels

class TestRemoveVowels(unittest.TestCase):
    def test_remove_vowels_empty_string(self):
        self.assertEqual(remove_vowels(""), "")

    def test_remove_vowels_all_vowels(self):
        self.assertEqual(remove_vowels("aeiouAEIOU"), "")

    def test_remove_vowels_no_vowels(self):
        self.assertEqual(remove_vowels("bcdfg"), "bcdfg")

    def test_remove_vowels_mixed_case_vowels(self):
        self.assertEqual(remove_vowels("AaBbEe"), "Bb")

    def test_remove_vowels_whitespace_and_punctuation(self):
        self.assertEqual(remove_vowels("Hello, World! 123"), "Hll, Wrld! 123")

    def test_remove_vowels_newline_handling(self):
        self.assertEqual(remove_vowels("a\nb\nc"), "\nb\nc")

    def test_remove_vowels_unicode_non_ascii_vowels_remain(self):
        self.assertEqual(remove_vowels("áéíóúÁÉÍÓÚ"), "áéíóúÁÉÍÓÚ")

    def test_remove_vowels_single_characters(self):
        self.assertEqual(remove_vowels("a"), "")
        self.assertEqual(remove_vowels("b"), "b")
        self.assertEqual(remove_vowels("A"), "")
        self.assertEqual(remove_vowels("B"), "B")

    def test_remove_vowels_large_string(self):
        large_input = ("abcdefghijklmnopqrstuvwxyz" * 1000)
        expected = "".join([c for c in large_input if c.lower() not in "aeiou"])
        self.assertEqual(remove_vowels(large_input), expected)

    def test_remove_vowels_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            remove_vowels(None)

    def test_remove_vowels_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            remove_vowels(123)

    def test_remove_vowels_bytes_input_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            remove_vowels(b"abc")

    def test_remove_vowels_return_type_is_string(self):
        result = remove_vowels("abcdef")
        self.assertIsInstance(result, str)

    def test_remove_vowels_idempotent(self):
        original = "Hello World"
        first_pass = remove_vowels(original)
        second_pass = remove_vowels(first_pass)
        self.assertEqual(first_pass, second_pass)

    def test_remove_vowels_non_iterable_input_error(self):
        class NonIterable:
            pass
        with self.assertRaises(TypeError):
            remove_vowels(NonIterable())

    def test_remove_vowels_list_of_strings_return_expected(self):
        input_list = ["a", "b", "c"]
        result = remove_vowels(input_list)
        self.assertEqual(result, "bc")

    def test_remove_vowels_object_without_lower_attribute_raises_attribute_error(self):
        class Dummy:
            def __iter__(self):
                return iter([1, 2, 3])
        with self.assertRaises(AttributeError):
            remove_vowels(Dummy())

if __name__ == "__main__":
    unittest.main()
